1	import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
2	import { TestBed } from '@angular/core/testing';
3	import { Subject, of, throwError } from 'rxjs';
4	import { VeranstaltungenService } from '../shared/api/veranstaltungen.service';
5	import { Sitzplan, SitzplanPosition, SitzplanReihe } from '../shared/models/sitzplan';
6	import { Buchung } from './buchung';
7	
8	describe('Buchung', () => {
9	  function positionenFuerReihe(belegteCodes: string[], reihe: string): SitzplanPosition[] {
10	    const positionen: SitzplanPosition[] = [];
11	    for (let spalte = 1; spalte <= 10; spalte++) {
12	      if (spalte === 6) {
13	        positionen.push({ spalte, typ: 'Gang', code: null, status: null });
14	      } else {
15	        const code = `${reihe}${spalte}`;
16	        positionen.push({
17	          spalte,
18	          typ: 'Sitzplatz',
19	          code,
20	          status: belegteCodes.includes(code) ? 'Belegt' : 'Frei',
21	        });
22	      }
23	    }
24	    return positionen;
25	  }
26	
27	  function erzeugeR2Sitzplan(): Sitzplan {
28	    const belegteCodes = ['B3', 'B4', 'C7'];
29	    const reihen: SitzplanReihe[] = ['A', 'B', 'C', 'D', 'E', 'F'].map((reihe) => ({
30	      reihe,
31	      positionen: positionenFuerReihe(belegteCodes, reihe),
32	    }));
33	    return { veranstaltungId: 'E1', raumId: 'R2', raumName: 'Kleiner Saal', reihen };
34	  }
35	
36	  function createFixture(serviceStub: Pick<VeranstaltungenService, 'getSitzplan'>) {
37	    TestBed.configureTestingModule({
38	      imports: [Buchung],
39	      providers: [
40	        provideRouter([]),
41	        { provide: VeranstaltungenService, useValue: serviceStub },
42	        { provide: ActivatedRoute, useValue: { paramMap: of(convertToParamMap({ id: 'E1' })) } },
43	      ],
44	    });
45	    return TestBed.createComponent(Buchung);
46	  }
47	
48	  it('rendert an einer Gang-Position keine app-seat-tile, sondern eine sitzplan__luecke', () => {
49	    const fixture = createFixture({ getSitzplan: () => of(erzeugeR2Sitzplan()) });
50	    fixture.detectChanges();
51	
52	    const ersteReihe: HTMLElement = fixture.nativeElement.querySelector('.sitzplan__reihe');
53	    expect(ersteReihe.querySelector('.sitzplan__luecke')).not.toBeNull();
54	    expect(ersteReihe.querySelectorAll('app-seat-tile').length).toBe(9);
55	  });
56	
57	  it('rendert für eine belegte Sitzplatz-Position eine app-seat-tile mit Status belegt', () => {
58	    const fixture = createFixture({ getSitzplan: () => of(erzeugeR2Sitzplan()) });
59	    fixture.detectChanges();
60	
61	    const kacheln: HTMLElement[] = Array.from(
62	      fixture.nativeElement.querySelectorAll('app-seat-tile'),
63	    );
64	    const belegteKachel = kacheln.find((k) =>
65	      k.querySelector('.seat-tile')?.getAttribute('aria-label')?.includes('belegt'),
66	    );
67	    expect(belegteKachel).toBeDefined();
68	  });
69	
70	  it('rendert für die R2-Geometrie 54 app-seat-tile-Elemente und 6 sitzplan__luecke-Elemente', () => {
71	    const fixture = createFixture({ getSitzplan: () => of(erzeugeR2Sitzplan()) });
72	    fixture.detectChanges();
73	
74	    expect(fixture.nativeElement.querySelectorAll('app-seat-tile').length).toBe(54);
75	    expect(fixture.nativeElement.querySelectorAll('.sitzplan__luecke').length).toBe(6);
76	  });
77	
78	  it('zeigt vor Auflösung den Skeleton-Container an, keine app-seat-tile', () => {
79	    const nichtAufgeloest = new Subject<Sitzplan>();
80	    const fixture = createFixture({ getSitzplan: () => nichtAufgeloest.asObservable() });
81	    fixture.detectChanges();
82	
