    expect(fixture.nativeElement.textContent).not.toContain('✓');
    expect(kachel.getAttribute('aria-label')).toBe('Reihe B, Platz 3, frei');
  });

  it('setzt tabindex="0" bei fokussierbar=true und tabindex="-1" bei fokussierbar=false', () => {
    const fokussierteFixture = createFixture('B', 3, 'Frei', { fokussierbar: true });
    const fokussierteKachel: HTMLElement =
      fokussierteFixture.nativeElement.querySelector('.seat-tile');
    expect(fokussierteKachel.getAttribute('tabindex')).toBe('0');

    const nichtFokussierteFixture = createFixture('B', 4, 'Frei', { fokussierbar: false });
    const nichtFokussierteKachel: HTMLElement =
      nichtFokussierteFixture.nativeElement.querySelector('.seat-tile');
    expect(nichtFokussierteKachel.getAttribute('tabindex')).toBe('-1');
  });
});

